SELECT r.revision, r.report_run_id, r.owner_id, r.materializer, r.requested_params_json, r.effective_params_json, r.status, r.started_at, r.ui_run_request_id, r.report_spec_json, r.report_fill_json, r.report_print_json, r.created_at, r.updated_at, r.conversation_id, r.origin, r.builder_ref, r.preset_id, r.source_kind, r.source_id, r.failure_code, r.failure_text, r.completed_at, r.activation_source, r.adoption_source, r.actor_id FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM report_run c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)